Interactive Simulation
Below is a live simulation running directly in your browser using Observable JS.
Instructions: 1. Wait a moment for the pattern to grow from the center. 2. Click and Drag on the canvas to add more chemical manually. 3. Adjust Sliders: Change \(F\) and \(k\) to discover different “species” (Coral, Spots, Worms).



Code
viewof F = Inputs.range([0.01, 0.1], {label: "Feed Rate (F)", value: 0.0545, step: 0.0001})
viewof k = Inputs.range([0.03, 0.07], {label: "Kill Rate (k)", value: 0.0620, step: 0.0001})
viewof brushSize = Inputs.range([1, 50], {label: "Brush Size", value: 10, step: 1})

// 2. The Canvas
canvas = DOM.canvas(800, 400)

// 3. The Simulation Logic
{
  const ctx = canvas.getContext("2d");
  const w = canvas.width;
  const h = canvas.height;

  // Initialize Grids
  let u = new Float32Array(w * h).fill(1.0);
  let v = new Float32Array(w * h).fill(0.0);
  let u_next = new Float32Array(w * h).fill(1.0);
  let v_next = new Float32Array(w * h).fill(0.0);

  // Seed a central square
  for (let i = w/2 - 10; i &lt; w/2 + 10; i++) {
    for (let j = h/2 - 10; j &lt; h/2 + 10; j++) {
      v[j * w + i] = 1.0;
    }
  }

  // Parameters
  const Du = 0.2; // Diffusion u (Speed optimized)
  const Dv = 0.1; // Diffusion v
  const dt = 1.0;

  // Mouse Interaction
  let isDrawing = false;
  canvas.onmousedown = () =&gt; isDrawing = true;
  canvas.onmouseup = () =&gt; isDrawing = false;
  canvas.onmousemove = (e) =&gt; {
    if (!isDrawing) return;
    const rect = canvas.getBoundingClientRect();
    const x = Math.floor((e.clientX - rect.left) / (rect.width/w));
    const y = Math.floor((e.clientY - rect.top) / (rect.height/h));

    for(let dy=-brushSize; dy&lt;=brushSize; dy++) {
        for(let dx=-brushSize; dx&lt;=brushSize; dx++) {
            if (dx*dx + dy*dy &lt;= brushSize*brushSize) {
                const idx = (y+dy)*w + (x+dx);
                if (idx &gt;= 0 && idx &lt; w*h) v[idx] = 1.0;
            }
        }
    }
  };

  // Main Loop
  while (true) {
    // Run multiple steps per frame for speed
    for(let steps=0; steps&lt;8; steps++) {
      for (let y = 1; y &lt; h - 1; y++) {
        for (let x = 1; x &lt; w - 1; x++) {
          const i = y * w + x;

          // Laplacian (Simple 5-point stencil)
          const lapU = (u[i-1] + u[i+1] + u[i-w] + u[i+w] - 4*u[i]);
          const lapV = (v[i-1] + v[i+1] + v[i-w] + v[i+w] - 4*v[i]);

          const uvv = u[i] * v[i] * v[i];

          // Gray-Scott Update
          u_next[i] = u[i] + (Du * lapU - uvv + F * (1 - u[i])) * dt;
          v_next[i] = v[i] + (Dv * lapV + uvv - (k + F) * v[i]) * dt;

          // Constrain
          u_next[i] = Math.max(0, Math.min(1, u_next[i]));
          v_next[i] = Math.max(0, Math.min(1, v_next[i]));
        }
      }
      // Swap buffers
      [u, u_next] = [u_next, u];
      [v, v_next] = [v_next, v];
    }

    // Render
    const imgData = ctx.createImageData(w, h);
    const data = imgData.data;
    for (let i = 0; i &lt; w * h; i++) {
        const val = v[i];
        // Visualization: Map Chemical V to a Cyan/Blue color map
        // R=0, G=255*val, B=255
        data[4*i + 0] = 0;             // R
        data[4*i + 1] = Math.floor(val * 255); // G
        data[4*i + 2] = Math.floor(Math.min(255, val * 255 + 50)); // B
        data[4*i + 3] = 255;           // Alpha
    }
    ctx.putImageData(imgData, 0, 0);

    yield canvas; // Wait for next animation frame
  }
}
